import React from 'react'
import {DashboardBackground, BodyContainer, InlineContainer, InlineTittle} from './styles';

import Header from '../../components/Header';
import Card from '../../components/Card';

const Dashboard = ()=>{

    
    return(
       <DashboardBackground>
           <Header />
           <BodyContainer>
               <Card noShadow width='90%'>
                   <InlineTittle>
                       <h2>Register</h2>
                   </InlineTittle>
               </Card>
               
           </BodyContainer>

       </DashboardBackground>
            
        
    )
}

export default Dashboard;
